import React, { useState } from "react";
import Layout from "../components/Layout";
import api from "../services/api";

const Prescription = () => {
    const [formData, setFormData] = useState({
        name: "",
        medicines: "",
    });

    // Handle Change
    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value,
        });
    };

    // Generate PDF
    const handleGeneratePDF = async (e) => {
        e.preventDefault();

        try {
            const res = await api.post(
                "/prescription/pdf",
                formData,
                { responseType: "blob" } // important for PDF
            );

            // Download PDF
            const file = new Blob([res.data], { type: "application/pdf" });
            const link = document.createElement("a");
            link.href = window.URL.createObjectURL(file);
            link.download = "prescription.pdf";
            link.click();

            alert("✅ Prescription PDF Downloaded");
        } catch (error) {
            console.log(error);
            alert("❌ Failed to Generate PDF (Check JWT Token)");
        }
    };

    return (
        <Layout>
            <div className="container-fluid">

                <h2 className="fw-bold mb-4">💊 Prescription PDF Generator</h2>

                <div className="card shadow-lg border-0">
                    <div className="card-header bg-primary text-white fw-bold">
                        Create Prescription
                    </div>

                    <div className="card-body">
                        <form onSubmit={handleGeneratePDF}>
                            <div className="row g-3">

                                {/* Patient Name */}
                                <div className="col-md-6">
                                    <label className="form-label">Patient Name</label>
                                    <input
                                        type="text"
                                        name="name"
                                        value={formData.name}
                                        onChange={handleChange}
                                        className="form-control"
                                        placeholder="Enter patient name"
                                        required
                                    />
                                </div>

                                {/* Medicines */}
                                <div className="col-md-12">
                                    <label className="form-label">Medicines</label>
                                    <textarea
                                        name="medicines"
                                        value={formData.medicines}
                                        onChange={handleChange}
                                        className="form-control"
                                        placeholder="Paracetamol 2x daily..."
                                        rows="4"
                                        required
                                    />
                                </div>

                                {/* Button */}
                                <div className="col-md-12 text-end">
                                    <button type="submit" className="btn btn-success px-4">
                                        📄 Generate PDF
                                    </button>
                                </div>

                            </div>
                        </form>
                    </div>
                </div>

            </div>
        </Layout>
    );
};

export default Prescription;
